const body = $json.body;

const fail = (details) => ({
  json: {
    valid: false,
    response: {
      error: 'invalid_request',
      details,
    },
  },
});

if (!body || typeof body !== 'object' || Array.isArray(body)) {
  return fail(['body must be a JSON object']);
}

const allowedKeys = ['duration', 'language', 'topic'];
const actualKeys = Object.keys(body).sort();
const extraKeys = actualKeys.filter((key) => !allowedKeys.includes(key));
const missingKeys = allowedKeys.filter((key) => !actualKeys.includes(key));

const errors = [];
if (extraKeys.length) errors.push('unexpected fields: ' + extraKeys.join(', '));
if (missingKeys.length) errors.push('missing fields: ' + missingKeys.join(', '));

let topic = '';
if (typeof body.topic !== 'string') {
  errors.push('topic must be a string');
} else {
  topic = body.topic.trim();
  if (topic.length < 3 || topic.length > 500) {
    errors.push('topic length must be between 3 and 500 characters');
  }
}

const language = body.language;
if (typeof language !== 'string' || !['en', 'pl', 'ru', 'uk'].includes(language)) {
  errors.push('language must be one of: en, pl, ru, uk');
}

const duration = body.duration;
if (!Number.isInteger(duration) || ![15, 30, 45, 60].includes(duration)) {
  errors.push('duration must be one of: 15, 30, 45, 60');
}

if (errors.length) return fail(errors);

return {
  json: {
    valid: true,
    topic,
    language_code: language,
    target_duration_seconds: duration,
  },
};

