const jobId = typeof $json.job_id === 'string' ? $json.job_id.trim() : '';
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(jobId)) {
  throw new Error('create_job returned an invalid job_id');
}
return { json: { job_id: jobId } };

const response = $json.response && typeof $json.response === 'object'
  ? $json.response
  : { error: 'invalid_request', details: ['request validation failed'] };
return { json: response };
